(window.TNQ=window.TNQ||[]).push({"terms":{"반열방":{"d":"선교사 메리 놀스가 세운 한국 최초의 사회복지 시설 가운데 하나입니다.","r":["태화여자관"]},"태화여자관":{"d":"메리 마이어스가 설립한 한국 최초의 사회복지관이다.","r":[]},"사회적 자본":{"d":"신뢰와 네트워크처럼 협력을 가능하게 하는 공동체의 무형 자산입니다.","r":["네트워크"]},"네트워크":{"d":"사람이나 조직이 서로 연결된 관계망으로 사회적 자본의 전제가 됩니다.","r":["사회적 자본"]},"표적체계":{"d":"변화를 일으키려고 영향을 주어야 하는 대상 체계입니다.","r":[]},"사회자본":{"d":"신뢰, 호혜성, 네트워크 같은 관계적 자원으로 집합적 자산이 된다.","r":[]},"기능적 공동체":{"d":"지리적 범위가 아니라 공통의 관심이나 직업, 정체성으로 결합한 공동체이다.","r":[]},"멤버십":{"d":"공동체 구성원으로서 갖는 소속 자격이다.","r":[]},"지역사회유형":{"d":"던햄이 인구 크기, 산업구조, 인구구성 등을 기준으로 나눈 지역사회의 분류이다.","r":[]},"지역사회 비교척도":{"d":"워렌이 지역사회를 비교하기 위해 제시한 기준으로 지역적 자치성, 서비스 영역의 일치, 주민의 심리적 일체감, 수평적 유형 등이 있다.","r":[]},"수평적 유형":{"d":"워렌이 말한 지역사회 내 상이한 단위 조직들 사이의 구조적, 기능적 관련 정도이다.","r":[]},"생산ㆍ분배ㆍ소비":{"d":"길버트와 스펙트가 제시한 지역사회 기능의 하나로 주민이 필요한 재화와 서비스를 공급받는 기능이다.","r":[]},"사회화":{"d":"길버트와 스펙트가 제시한 지역사회 기능으로 지역사회가 공유하는 지식, 가치, 행동양식을 구성원에게 전달하는 기능이다.","r":[]},"사회통제":{"d":"길버트와 스펙트가 제시한 지역사회 기능으로 구성원이 사회적 규범에 따르도록 하는 기능이다.","r":[]},"상부상조":{"d":"길버트와 스펙트가 제시한 지역사회 기능으로 사회적 위험에 직면한 구성원을 서로 돕는 기능이다.","r":[]},"사회통합":{"d":"길버트와 스펙트가 제시한 지역사회 기능의 하나로 구성원이 사회적 관계로 결합해 공동체를 이루는 기능이다.","r":[]},"정상화":{"d":"장애인이 일반 사회의 생활 조건에서 살 수 있도록 해야 한다는 지역사회복지의 가치이다.","r":[]},"탈시설화":{"d":"시설 수용 보호에서 벗어나 지역사회에서 살도록 하는 흐름이다.","r":[]},"다원주의이론":{"d":"권력이 여러 집단에 분산되어 있고 집단 간 경쟁과 협상으로 결정된다고 보는 이론이다.","r":[]},"구조기능론":{"d":"사회를 상호의존적인 부분으로 구성된 체계로 보고 각 부분의 기능을 분석하는 이론이다.","r":[]},"사회자본이론":{"d":"신뢰, 호혜성, 네트워크 같은 사회적 관계의 자산이 지역사회 문제 해결에 도움이 된다고 보는 이론이다.","r":[]},"호혜성":{"d":"서로 도움을 주고받는 관계의 성질이다.","r":[]},"사회체계이론":{"d":"지역사회를 상호의존적인 부분들로 구성된 체계로 보며 체계와 경계 개념을 사용한다.","r":[]},"생태학적 관점":{"d":"지역사회를 인간과 환경의 상호작용으로 보며 분리, 경쟁, 침입, 계승 같은 개념을 쓴다.","r":[]},"교환이론":{"d":"사회관계를 이익과 보상의 교환으로 설명하며 자원의 교환을 통한 지역사회 발전을 강조한다.","r":[]},"자원동원이론":{"d":"사회운동의 성패가 조직원 충원, 자금 조달, 조직구조 개발 능력에 있다고 보는 이론이다.","r":[]},"권력의존이론":{"d":"조직이 자원을 가진 다른 조직에 의존하는 정도에 따라 통제를 받는다고 보는 이론이다.","r":[]},"갈등이론":{"d":"사회를 이해관계 대립과 불평등한 분배에서 비롯된 갈등으로 보고 갈등을 변화의 동력으로 보는 이론이다.","r":[]},"사회학습이론":{"d":"타인의 행동을 관찰하고 모방하며 학습한다고 보는 이론이다.","r":[]},"우애방문단":{"d":"자선조직협회의 방문 활동가들로 빈민을 방문해 개별적으로 돕는 활동을 하였다.","r":[]},"자선조직협회":{"d":"COS라 하며 중복 구호를 방지하기 위해 설립되었고 사회진화론의 영향을 받았다.","r":[]},"인보관":{"d":"빈곤 지역에 거주하며 주민과 함께 생활하며 사회개혁을 도모한 복지관으로 토인비홀과 헐하우스가 대표적이다.","r":[]},"토인비홀":{"d":"1884년 바네트 목사가 영국 런던에 설립한 최초의 인보관이다.","r":[]},"헐하우스":{"d":"제인 아담스가 미국 시카고에 설립한 인보관이다.","r":[]},"지역사회보호":{"d":"시설 수용 대신 지역사회 안에서 돌봄을 제공하는 방식이다.","r":[]},"그리피스 보고서":{"d":"1980년대 영국에서 지역사회보호의 책임이 지방정부에 있음을 강조한 보고서이다.","r":[]},"새마을운동":{"d":"근면, 자조, 협동을 기본정신으로 한 정부 주도의 지역사회 개발 운동이다.","r":[]},"향약":{"d":"조선시대 주민 교화와 상호 부조를 위해 지식인이 조직한 자치적 협동 조직이다.","r":[]},"웨일과 갬블":{"d":"지역사회복지 실천모델을 여러 유형으로 구분해 제시한 학자들이다.","r":[]},"로스만":{"d":"지역사회개발, 사회계획, 사회행동의 세 가지 실천모델을 제시한 학자이다.","r":[]},"지역사회개발모델":{"d":"주민의 참여와 역량 강화로 지역사회 문제를 해결하는 모델이다. 사회복지사는 조력자, 촉진자, 교육자 역할을 한다.","r":[]},"사회계획모델":{"d":"전문가가 문제를 분석해 계획을 수립하고 서비스를 조정하는 모델이다.","r":[]},"사회행동모델":{"d":"권리를 박탈당한 집단의 이익을 대변해 권력 구조의 변화를 요구하는 모델이다.","r":[]},"지역사회연계":{"d":"테일러와 로버츠 모델에서 지역사회 기관 간의 연결 체계를 강화하는 모델이다.","r":[]},"프로그램 개발 및 조정":{"d":"테일러와 로버츠 모델의 하나로 서비스 프로그램을 개발하고 조정하는 모델이다.","r":[]},"조력자":{"d":"주민이 스스로 문제를 해결하도록 돕는 지역사회개발모델의 사회복지사 역할이다.","r":[]},"옹호":{"d":"소외되고 억압받는 집단의 입장을 대변하고 권리 보호를 주장하는 활동이다.","r":[]},"임파워먼트":{"d":"주민의 강점을 인정해 스스로 삶을 결정할 수 있도록 역량을 강화하는 것이다.","r":[]},"조직화":{"d":"지역주민이 주체가 되어 지역사회 문제를 해결하도록 주민을 모으고 운영하는 기술이다.","r":[]},"네트워크 기술":{"d":"지역사회의 기관과 자원을 연결해 서비스 중복과 누락을 막는 실천 기술이다.","r":[]},"의식화":{"d":"주민이 개인 문제와 사회구조의 관련성을 깨닫게 하는 것이다.","r":[]},"사례관리":{"d":"복합적 욕구를 가진 대상자에게 자원을 연결해 지속적으로 서비스를 관리하는 방식이다.","r":[]},"지역사회보장계획":{"d":"시군구가 지역사회보장협의체 심의를 거쳐 4년마다 수립하는 사회보장 계획이다.","r":[]},"지역사회보장협의체":{"d":"지역사회보장에 관한 사항을 심의, 자문하는 협의 기구이다.","r":[]},"실무협의체":{"d":"지역사회보장협의체의 분과로 실무적 사항을 협의하는 협의체이다.","r":[]},"지방분권":{"d":"중앙정부의 권한을 지방정부로 이양하는 것이다.","r":[]},"사회복지협의회":{"d":"사회복지 관련 기관과 단체 간의 연계, 협력, 조정을 수행하는 협의 단체이다.","r":[]},"사회복지공동모금회":{"d":"사회복지공동모금을 수행하는 사회복지법인으로 모금과 배분을 담당한다.","r":[]},"사회적 경제":{"d":"이윤 극대화보다 사람의 가치를 우위에 두는 경제 활동으로 사회적 기업, 협동조합 등이 참여한다.","r":[]},"자활기업":{"d":"저소득층이 자활을 위해 공동으로 운영하는 기업이다.","r":[]},"마을기업":{"d":"지역 주민이 지역 자원을 활용해 수익을 내고 지역 문제를 해결하는 기업으로 공동체성, 공공성, 지역성, 기업성을 운영 원칙으로 한다.","r":[]},"운영위원회":{"d":"사회복지관의 프로그램 개발과 평가 등을 심의하는 위원회이다.","r":[]},"지역조직화":{"d":"사회복지관 기능 중 주민 조직화와 자원봉사자 개발, 관리를 하는 기능이다.","r":[]},"지역사회상실":{"d":"산업화와 도시화로 전통사회의 지역사회 기능이 약화되었다고 보는 관점이다.","r":[]},"사회복지공동모금지회":{"d":"시도 단위로 두는 사회복지공동모금회의 지부이다.","r":[]},"한국사회복지협의회":{"d":"사회복지사업법에 근거한 민간 법정 단체로 사회복지 기관 간 연계, 협력, 조정을 수행한다.","r":[]},"지역사회조직화":{"d":"사회복지관 사업 기능의 하나로 주민 조직화, 자원 개발, 자원봉사자 관리를 하는 기능이다.","r":[]},"서비스 제공 기능":{"d":"사회복지관 사업 기능의 하나로 상담, 교육, 자활 등 직접 서비스를 제공하는 기능이다.","r":[]},"사회적기업":{"d":"취약계층에 사회서비스나 일자리를 제공하며 영업활동을 하는 기업이다.","r":[]},"협동조합":{"d":"조합원의 권익을 높이고 지역사회에 공헌하려고 설립하는 조직이다.","r":[]},"도시재생":{"d":"쇠퇴한 도시를 물리적, 사회적으로 되살리는 사업이다.","r":[]},"자원봉사센터":{"d":"자원봉사 프로그램을 개발하고 자원봉사자를 연결, 관리하는 기관이다.","r":[]},"자원봉사활동 추진체계":{"d":"자원봉사활동 진흥을 위해 국가와 지방자치단체, 센터 등이 맡은 역할의 체계이다.","r":[]},"지역사회복지운동":{"d":"주민 삶의 질과 관련된 생활영역에서 부당한 권력구조를 바꾸려는 조직적 운동이다.","r":[]},"사회권":{"d":"인간다운 생활을 국가에 요구할 수 있는 권리이다.","r":[]},"아른스테인":{"d":"주민참여를 여러 단계로 분류한 사다리 모형을 제시한 학자이다.","r":[]},"주민참여":{"d":"지역 주민이 계획과 결정 과정에 참여하는 것이다.","r":[]},"주민회유":{"d":"아른스테인의 주민참여 단계 중 주민 의견을 듣지만 영향력은 제한되는 형식적 참여 단계이다.","r":[]},"주민동원":{"d":"아른스테인의 주민참여 단계 중 주민을 행사에 동원하는 낮은 수준의 참여 단계이다.","r":[]},"정보제공":{"d":"아른스테인의 주민참여 단계 중 주민에게 일방적으로 정보를 알려 주는 단계이다.","r":[]},"마을만들기":{"d":"주민이 주체가 되어 마을의 환경과 공동체를 가꾸는 사업이다.","r":[]},"조례제정운동":{"d":"주민이 지방자치단체의 조례 제정을 요구해 제도 변화를 이끄는 운동이다.","r":[]}},"notes":{"Griffiths: 지방정부의 책임을 강조":"그리피스 보고서는 지역사회돌봄에서 지방정부가 맡을 책임을 강조했습니다.","「협동조합 기본법」에 따라 자활공동체에서 명칭이 변경되었다":"자활기업은 협동조합 기본법에 따라 자활공동체라는 명칭이 바뀐 것입니다.","개인의 문제와 제도적 권력관계의 연관성을 깨닫도록 하는 노력이 중요하다":"임파워먼트에서는 개인의 문제가 제도와 권력관계에서 비롯됨을 깨닫도록 돕는 노력이 핵심입니다.","구체적인 실행계획 단계에서는 정책 접근법, 프로그램 접근법, 프로젝트 접근법 등을 사용한다":"계획 단계에서 구체적인 실행계획을 세울 때는 정책, 프로그램, 프로젝트 접근법을 씁니다.","권리가 박탈당한 사람의 이익을 대변한다":"사회행동모델은 권리를 빼앗긴 사람들의 이익을 대신해 목소리를 냅니다.","기본정신은 근면, 자조, 협동, 정부가 지정한 새마을의 날은 매년 4월 22일":"새마을운동은 근면, 자조, 협동을 기본정신으로 하며 새마을의 날은 정부가 매년 4월 22일로 정했습니다.","네트워크는 사회적 자본의 전제가 된다, 지역사회의 집합적 자산으로서 의미를 가진다":"네트워크는 사회적 자본이 생기는 전제이고 지역사회가 함께 가진 자산이라는 의미가 있습니다.","농촌 새마을운동에서 도시 새마을운동으로 확대":"새마을운동은 농촌에서 시작해 도시 새마을운동으로 영역을 넓혔습니다.","농촌생활환경 개선운동으로 시작한 이 운동은 소득증대운동으로 발전하지 못하였다":"농촌생활환경 개선운동으로 출발한 새마을운동은 소득증대운동으로까지 발전하지 못했다는 설명은 틀립니다.","메리 놀스(M. Knowles)에 의해 반열방이 설립":"메리 놀스가 선교사로서 세운 시설이 반열방입니다.","모금회가 아닌 자는 사회복지공동모금 또는 이와 유사한 명칭을 사용하지 못한다":"모금회가 아닌 곳은 사회복지공동모금 같은 이름이나 비슷한 이름을 쓸 수 없습니다.","변화를 위한 기본 전략은 ‘억압자에 대항하기 위한 규합’을 추구":"사회행동모델의 변화 전략은 억압하는 쪽에 맞서려고 힘을 모으는 규합입니다.","변화 매개체는 과업지향적 소집단, 조직화를 위한 구성원의 능력개발에 초점을 둔다":"개발모델은 과업지향적 소집단을 변화 매개체로 삼고 조직화를 위해 구성원의 능력 개발에 초점을 둡니다.","변화 매개체로 대중조직을 활용":"사회행동모델은 대중조직을 변화의 수단으로 삼습니다.","복지권리ㆍ시민의식을 배양하는 사회권 확립운동":"복지권리와 시민의식을 키우는 사회권 확립운동도 지역사회복지운동의 활동입니다.","사무엘 바네트(S. Barnett) 목사가 설립한 인보관":"토인비홀은 사무엘 바네트 목사가 세운 영국의 인보관입니다.","사회복지 관련 기관ㆍ단체 간의 연계ㆍ협력ㆍ조정 등을 수행한다":"협의회는 사회복지 관련 기관과 단체 사이의 연계, 협력, 조정을 맡습니다.","사회복지사의 역할은 분석가, 행정가 등":"사회계획모델에서 사회복지사는 분석가나 행정가 역할을 합니다.","사회복지사의 주요 역할은 조직가, 교육자, 촉진자, 코치":"개발모델에서 사회복지사는 조직가, 교육자, 촉진자, 코치로 일합니다.","사회복지서비스의 책임과 권한이 지방에 이양된다":"지방분권이 이루어지면 사회복지서비스의 책임과 권한이 지방으로 넘어갑니다.","사회복지시설의 서비스 중복ㆍ누락을 방지할 수 있다":"연계기술은 시설들의 서비스가 겹치거나 빠지는 일을 막아 줍니다.","사회복지 실무자도 포함되며, 사회복지전문가, 지역활동가, 지역사회복지이용자 등 다양하다":"운동의 주체에는 사회복지 실무자뿐 아니라 전문가, 지역활동가, 이용자도 포함됩니다.","사회복지에 관한 조사ㆍ연구 및 정책을 건의한다":"사회복지협의회는 사회복지에 관한 조사와 연구를 하고 정책을 건의합니다.","사회복지활동 등을 지원하기 위한 재원을 조성하기 위하여 복권을 발행할 수 있다":"공동모금회는 사회복지활동 지원 재원을 만들려고 복권을 발행할 수 있습니다.","사회서비스의 협력과 통합을 제안":"시봄보고서는 영국에서 사회서비스를 서로 협력하고 통합하자고 제안한 보고서입니다.","사회자본을 만들기 위해 지역주민들이 서로에 대한 책임감을 인식하도록 돕는다":"사회자본을 만들려면 주민들이 서로에게 책임감을 갖도록 돕습니다.","새로운 인프라 구축에 필요한 시간과 비용을 줄일 수 있다":"연계기술로 새 인프라를 만드는 데 드는 시간과 비용을 아낄 수 있습니다.","새마을운동중앙본부가 창립되어 민간주도로 전환":"새마을운동중앙본부가 창립되면서 운동의 주도권이 정부에서 민간으로 넘어갔습니다.","수립 및 지역사회보장조사의 시기ㆍ방법 등에 필요한 사항은 대통령령으로 정한다":"보장계획의 수립 방식과 지역사회보장조사를 언제 어떻게 할지는 대통령령이 정합니다.","시ㆍ도 및 시ㆍ군ㆍ구 단위에도 의무 설치한다":"협의회는 시ㆍ도뿐 아니라 시ㆍ군ㆍ구 단위에도 법에 따라 의무적으로 설치합니다.","시ㆍ도 사회복지협의회는 한국사회복지협의회의 지회로 운영된다":"시ㆍ도의 협의회는 독립 기관이 아니라 한국사회복지협의회의 지회로서 운영됩니다.","신뢰는 공동체의 문제를 해결할 수 있는 자원이다":"신뢰는 공동체가 겪는 문제를 풀어 갈 수 있는 자원이 됩니다.","여성운동, 빈민운동, 환경운동 등 시민운동에도 활용될 수 있다":"여성운동, 빈민운동, 환경운동 같은 시민운동에도 이 모델을 쓸 수 있습니다.","우리나라는 지방자치법의 제정으로 도입되었다":"우리나라의 지방자치는 지방자치법이 제정되면서 도입되었습니다.","운영 원칙은 공동체성, 공공성, 지역성, 기업성":"마을기업은 공동체성, 공공성, 지역성, 기업성을 운영 원칙으로 합니다.","위원은 10명 이상 40명 이하로 구성한다":"실무협의체는 위원 10명 이상 40명 이하로 구성합니다.","이용자 중심의 통합적 서비스를 제공할 수 있다":"연계기술로 이용자 중심의 통합적 서비스를 줄 수 있습니다.","이윤 극대화의 시장경제와 달리 사람의 가치를 우위에 두는 경제활동":"사회적 경제는 이윤 극대화가 목적인 시장경제와 달리 사람의 가치를 앞세우는 경제활동입니다.","이해관계의 대립을 불평등한 분배로 설명한다":"갈등이론에서는 이해관계가 맞서는 까닭을 자원이 불평등하게 분배되기 때문이라고 설명합니다.","일차적 구성원은 지역사회 이웃주민":"개발모델이 일차적으로 상대하는 구성원은 그 동네의 이웃주민입니다.","입법, 행정, 사법영역에서 다양한 형태로 전개되는 사회 정의와 복지 증진을 위한 활동":"정치 옹호는 입법, 행정, 사법 영역에서 사회 정의와 복지 증진을 위해 벌이는 활동입니다.","자원동원, 재정집행, 네트워크는 실행단계에서 수행된다":"실행 단계에서는 자원을 동원하고 재정을 집행하며 네트워크를 운영합니다.","조례제정운동과 같은 제도변화과정을 예로 들 수 있다":"조례제정운동처럼 제도를 바꾸어 가는 과정이 지역사회복지운동의 예입니다.","주민 교화 등을 목적으로 한 지식인 간의 자치적인 협동조직":"향약은 지식인들이 주민을 교화하려고 만든 자치적 협동조직입니다.","주민 삶의 질과 관련된 생활영역에 있다":"지역사회복지운동의 주된 관심사는 주민의 삶의 질과 관련된 생활영역입니다.","주민 스스로 자신을 옹호하기 어려운 상황에서 그 개인과 가족을 대신하여 수행하는 활동":"개인 옹호는 스스로 옹호하기 어려운 주민의 개인과 가족을 대신해 하는 활동입니다.","주민참여로 권력의 재분배가 이루어진다":"주민이 참여하면서 권력이 더 고르게 나뉘는 재분배가 이뤄집니다.","주요 기술과 기법은 갈등, 대결, 협상":"사회행동모델은 갈등, 대결, 협상이라는 기술과 기법을 주로 씁니다.","지방정부, 외부개발자, 지역주민을 변화의 표적체계로 본다":"실천모델에서 변화의 표적체계는 지방정부와 외부개발자, 지역주민입니다.","지역 간 상대적 박탈감으로 사회적 형평성 문제가 발생된다":"지역 간 상대적 박탈감이 생겨 사회적 형평성 문제가 나타납니다.","지역 간의 경쟁이 심화되어 지역 이기주의가 나타날 수 있다":"지방분권의 한계로 지역 간 경쟁이 심해져 지역 이기주의가 생길 수 있습니다.","지역복지 실현을 위해 중앙정부와 분담적 관계를 추구한다":"지역복지를 이루려고 지방은 중앙정부와 역할을 나누어 맡는 관계를 추구합니다.","지역복지 활성화의 토대가 될 수 있다":"지방분권은 지역복지가 활기를 띠는 토대가 될 수 있습니다.","지역사회 구성원간 신뢰와 호혜성이 형성되면 네트워크가 지속될 수 있다":"구성원 사이에 신뢰와 호혜성이 생기면 네트워크가 오래 이어질 수 있습니다.","지역사회 내 불평등한 권력구조의 변화를 지향":"사회행동모델은 지역사회의 불평등한 권력구조를 바꾸려 합니다.","지역사회 문제나 욕구는 지역사회 상황에 따라 다양한 형태로 나타날 수 있다":"문제나 욕구는 그 지역이 처한 상황에 따라 여러 모습으로 나타날 수 있습니다.","지역사회문제 해결과정으로 볼 수 있다":"실천은 문제를 하나씩 풀어 가는 과정으로 볼 수 있습니다.","지역사회보장협의체 심의를 거쳐 지방의회에 보고한다":"지역사회보장계획은 지역사회보장협의체가 심의한 뒤 지방의회에 보고합니다.","지역사회복지에 대한 자기통치 원리가 중요시된다":"지방분권에서는 지역이 스스로 다스리는 자기통치 원리가 중요시됩니다.","지역사회복지운동에는 다양한 이념이 사용될 수 있다":"복지운동은 하나의 이념에 갇히지 않고 다양한 이념을 쓸 수 있습니다.","지역사회 사정은 지역사회의 욕구와 자원을 파악하는 단계":"사정은 그 지역의 욕구가 무엇이고 쓸 수 있는 자원이 무엇인지 파악하는 단계입니다.","지역사회의 다양한 자원 활용 및 조직 간 유기적 협력이 이루어진다":"지역사회복지운동은 지역의 다양한 자원을 활용하고 조직 사이의 협력을 유기적으로 이룹니다.","지역사회의 부당한 권력구조를 변화시키기 위해 노력한다":"복지운동은 지역의 부당한 권력구조를 바꾸려고 노력합니다.","지역사회조직은 권력의 균형적인 배분을 위해 지역사회자원 개발에 힘써야 한다":"권력의 균형적 배분을 위해 지역사회조직은 자원을 개발하는 데 힘써야 한다는 입장입니다.","지역주민들과 함께 근본적인 제도상의 변화를 도모하는 활동":"체계변화 옹호는 지역주민과 함께 제도 자체의 근본적인 변화를 꾀하는 활동입니다.","지역주민의 의사를 반영한 행정서비스가 강화된다":"지방분권으로 주민 의사를 반영한 행정서비스가 강해집니다.","지역주민 참여를 위한 수요자 중심의 활동이 이루어진다":"지역사회복지운동은 수요자를 중심에 두고 주민 참여를 이끄는 활동을 합니다.","취약계층에게 사회서비스 또는 일자리를 제공한다":"사회적기업은 취약계층에게 사회서비스나 일자리를 제공하는 기업입니다.","클라이언트 중심의 사회적 관계망을 강화시킬 수 있다":"연계기술은 클라이언트를 중심에 둔 사회적 관계망을 튼튼하게 합니다.","태화여자관은 메리 마이어스(M. D. Myers)에 의해 설립":"태화여자관은 선교사 메리 마이어스가 설립한 시설입니다.","특별시ㆍ광역시ㆍ특별자치시ㆍ도ㆍ특별자치도 단위 사회복지공동모금지회를 둔다":"공동모금회는 특별시, 광역시, 도 등 단위로 지회를 둡니다.","특정 집단이 불이익을 받을 때 이들의 공동 문제를 해결하기 위한 활동":"집단 옹호는 특정 집단이 불이익을 받을 때 그 집단의 공동 문제를 풀기 위한 활동입니다.","한 번 형성된 후에도 소멸될 수 있다":"네트워크는 한번 만들어졌더라도 관리하지 않으면 사라질 수 있습니다.","효과적인 주민 조직화를 위해 주민의 개인적 이익에 대한 관심을 조직화에 활용할 수 있다":"주민 조직화를 효과적으로 하려면 주민 개인의 이익에 대한 관심을 이용할 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
